#include "qt/CockpitBridge.hpp"
#include "platform/AircraftPlatformCatalog.hpp"
#include <QVariantMap>
namespace nexvary::avionics { namespace {QStringList qsl(const std::vector<std::string>& v){QStringList o;for(const auto& x:v)o.push_back(QString::fromStdString(x));return o;}}
QVariantList CockpitBridge::platformProfiles()const{QVariantList rows;for(const auto& p:AircraftPlatformCatalog::profiles()){QVariantMap r;r["id"]=QString::fromStdString(p.id);r["name"]=QString::fromStdString(p.name);r["category"]=QString::fromStdString(p.category);r["propulsion"]=QString::fromStdString(p.propulsion);r["description"]=QString::fromStdString(p.description);r["systems"]=qsl(p.systems);r["channels"]=qsl(p.channels);r["diagnosticFamilies"]=qsl(p.diagnosticFamilies);r["trainingScenarios"]=qsl(p.trainingScenarios);r["systemCount"]=static_cast<int>(p.systems.size());r["channelCount"]=static_cast<int>(p.channels.size());r["diagnosticFamilyCount"]=static_cast<int>(p.diagnosticFamilies.size());r["scenarioCount"]=static_cast<int>(p.trainingScenarios.size());r["faultPresetCount"]=static_cast<int>(p.faultPresetIds.size());r["twinNodeCount"]=static_cast<int>(p.twinTopology.size());r["diagnosticRuleCount"]=static_cast<int>(p.diagnosticRules.size());r["active"]=p.id==activePlatformId_;rows.push_back(r);}return rows;}
QString CockpitBridge::activePlatformId()const{return QString::fromStdString(activePlatformId_);}QString CockpitBridge::activePlatformName()const{const auto p=AircraftPlatformCatalog::find(activePlatformId_);return p?QString::fromStdString(p->name):QStringLiteral("Generic Platform");}QString CockpitBridge::activePlatformCategory()const{const auto p=AircraftPlatformCatalog::find(activePlatformId_);return p?QString::fromStdString(p->category):QStringLiteral("GENERIC");}QString CockpitBridge::activePlatformPropulsion()const{const auto p=AircraftPlatformCatalog::find(activePlatformId_);return p?QString::fromStdString(p->propulsion):QStringLiteral("GENERIC");}
void CockpitBridge::setActivePlatform(const QString& id){const auto requested=id.toStdString();if(requested==activePlatformId_||!AircraftPlatformCatalog::find(requested))return;activePlatformId_=requested;replayMode_=false;replayPaused_=false;replayIndex_=0;diagnosticHistory_.clear();diagnosticSummary_=DiagnosticSummary{};lab_.reset();refresh(lab_.step());}
} // namespace nexvary::avionics
